RELATED=[(p['slug'],p['h1'].split(':')[0]) for p in PAGES]

def schemas(p):
    url=f"https://astrovip.ro/{p['slug']}/"
    faq={'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in p['faq']]}
    crumb={'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'AstroVip','item':'https://astrovip.ro/'},{'@type':'ListItem','position':2,'name':p['h1'],'item':url}]}
    page={'@context':'https://schema.org','@type':'WebPage','name':p['h1'],'url':url,'description':p['meta'],'inLanguage':'ro-RO','isPartOf':{'@type':'WebSite','name':'AstroVip','url':'https://astrovip.ro/'}}
    return '\n'.join('<script type="application/ld+json">'+json.dumps(x,ensure_ascii=False)+'</script>' for x in (page,crumb,faq))

def make_page(p):
    url=f"https://astrovip.ro/{p['slug']}/"
    sec=''.join(f'<section><h2>{html.escape(h)}</h2><p>{html.escape(t)}</p></section>' for h,t in p['sections'])
    faqs=''.join(f'<details><summary>{html.escape(q)}</summary><p>{html.escape(a)}</p></details>' for q,a in p['faq'])
    rel=''.join(f'<a href="/{slug}/">{html.escape(label)}</a>' for slug,label in RELATED if slug!=p['slug'])
    grid='<div class="planet-grid" data-planet-grid aria-live="polite"></div>' if p['slug']=='pozitii-planete-live' else ''
